import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link Fraction#percentageValue()}.
 */
public class Fraction_percentageValue_TriageGen3Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testPercentageValue_SimpleFraction() {
        // Fraction 1/2 = 0.5. 0.5 * 100 = 50.0
        Fraction fraction = new Fraction(1, 2);
        double expected = 50.0;
        assertEquals(expected, fraction.percentageValue(), DELTA);
    }












}

